const num=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))?Number(v):null;
function event(kind,title,detail){state.events.unshift({id:Date.now()+'-'+Math.random().toString(16).slice(2,6),kind,title,detail,time:Date.now()});state.events=state.events.slice(0,16)}
