async function feed(key,source,fn){const prev=state.feeds[key];state.feeds[key]={...prev,status:prev?.data?'refreshing':'loading',source};try{const data=await fn();state.feeds[key]={status:'live',source,data,receivedAt:Date.now()};}catch(e){state.feeds[key]={...prev,source,status:prev?.data?'stale':'unavailable',error:e.message,attemptedAt:Date.now()}}publish()}
