async function loadMarkets(){await feed('markets','CoinGecko',async()=>{const data=await get('https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&ids=bitcoin,ethereum&sparkline=true&price_change_percentage=24h',45000);if(!Array.isArray(data)||!data.length)throw new Error('No price data returned');return data.map(d=>({id:d.id,symbol:d.symbol,name:d.name,price:num(d.current_price),change:num(d.price_change_percentage_24h),volume:num(d.total_volume),cap:num(d.market_cap),points:d.sparkline_in_7d?.price||[],sourceTime:d.last_updated}))})}
