async function loadDex(){await feed('dex','DefiLlama',async()=>{let d=await get('https://api.llama.fi/overview/dexs?excludeTotalDataChart=true&excludeTotalDataChartBreakdown=true',180000);return {total24:num(d.total24h),change:num(d.change_1d),allChains:d.allChains||[],launchpads:(d.protocols||[]).filter(p=>p.category==='Launchpad').map(p=>({name:p.name,slug:p.slug,volume:num(p.total24h),change:num(p.change_1d),chains:p.chains||[]})).sort((a,b)=>(b.volume??-1)-(a.volume??-1))}});await Promise.allSettled(chains.map(c=>feed('dex-'+c.id,'DefiLlama',async()=>{let d=await get('https://api.llama.fi/overview/dexs/'+encodeURIComponent(c.llama)+'?excludeTotalDataChart=false&excludeTotalDataChartBreakdown=true',180000);if(num(d.total24h)===null)throw new Error('No aggregate reported');let history=(d.totalDataChart||[]).filter(p=>Array.isArray(p)&&num(p[1])!==null).slice(-62).map(p=>({time:Number(p[0])*1000,value:Number(p[1])}));return {name:c.name,volume:num(d.total24h),previous:num(d.total48hto24h),change:num(d.change_1d),history,latestChartDay:history.at(-1)?.time}}))) }
