async function loadLaunches(){await feed('launches','DEX Screener',async()=>{const profiles=await get('https://api.dexscreener.com/token-profiles/latest/v1',120000);if(!Array.isArray(profiles))throw new Error('Invalid profile response');const selected=profiles.filter(p=>chains.some(c=>c.id===p.chainId)).slice(0,24);const results=await Promise.allSettled(selected.map(p=>get('https://api.dexscreener.com/token-pairs/v1/'+encodeURIComponent(p.chainId)+'/'+encodeURIComponent(p.tokenAddress),120000)));let raw=results.filter(r=>r.status==='fulfilled'&&Array.isArray(r.value)).flatMap(r=>r.value);const map=new Map();raw.forEach(p=>{if(p.baseToken?.address&&p.pairAddress){const n=pair(p);if(n.createdAt&&n.createdAt>Date.now()-7*86400000){let key=n.chain+':'+n.address,prev=map.get(key);if(!prev||(n.liquidity??0)>(prev.liquidity??0))map.set(key,n)}}});let items=[...map.values()].sort((a,b)=>(b.volume1??0)-(a.volume1??0));const prev=state.feeds.launches?.data?.items;if(prev){let seen=new Set(prev.map(p=>p.id));let fresh=items.filter(p=>!seen.has(p.id)&&p.liquidity>=50000);if(fresh.length)event('launches',fresh.length+' newly observed pools','New in this feed; not a claim of complete launch discovery.')}return {items,sampledProfiles:selected.length,failedLookups:results.filter(r=>r.status==='rejected').length,coverage:'Latest token profiles, then pools under 7 days old. Sampled discovery, not all launches.'}})}
